cd /app && python3 << 'EOF'
import re
def parse(f):
    d={};cur=None
    for line in open(f):
        line=line.strip()
        if not line: continue
        if line.startswith('>'):
            cur=line[1:].strip(); d[cur]=''
        else: d[cur]+=line.lower()
    return d
d=parse('sequences.fasta')
inp=d['input']; egfp=d['egfp']; flag=d['flag']; snap=d['snap']; out=d['output']

def pref(seq):
    for L in range(len(seq),0,-1):
        if out.find(seq[:L])>=0: return L
    return 0
def suff(seq):
    for L in range(len(seq),0,-1):
        if out.find(seq[-L:])>=0: return L
    return 0

for name,seq in [('egfp',egfp),('flag',flag),('snap',snap)]:
    p=pref(seq); s=suff(seq)
    ppos=out.find(seq[:p]); send=out.find(seq[-s:])+s
    print(f'{name}: len={len(seq)} prefix_ok={p} suffix_ok={s} start_pos={ppos} end_pos={send} (full_match={p+len(seq)==2*len(seq) if False else (p==len(seq))})')
    print(f'   start={ppos}  clean_end_est={ppos+len(seq)}  suffix_end={send}')
    # region between ppos+len and send is the gap
    gap=send-(ppos+len(seq))
    print(f'   gap at end = {gap}')
EOF
